// ============================================================================
// Prepare — Code node (no credentials). Builds the knowledge base + a single
// batchEmbedContents request (all KB chunks + a memory-aware retrieval query),
// and loads the conversation memory (recent turns + rolling summary).
//
// PRODUCTION SWAP NOTE: for a large KB, embed the chunks once into a vector DB
// (Qdrant / Supabase pgvector) at ingest time and query it here instead.
// ============================================================================

const cfg = $('Config').first().json;
const wh = $('Chat Webhook').first().json;
const body = (wh && wh.body) ? wh.body : {};

const message = String(body.message || body.query || body.text || '').trim();
const sessionId = String(body.sessionId || body.session_id || 'anonymous').trim();

const KB = [
  { title: 'About Northwind Home Services', text: 'Northwind Home Services is a licensed, bonded and insured home-services company founded in 2009, serving the Greater Portland, Oregon metro area. We specialize in residential HVAC (heating, ventilation and air conditioning), plumbing, and electrical work. Our technicians are background-checked, drug-tested, and continuously trained. License #OR-CCB-204815.' },
  { title: 'Service Area', text: 'We serve the Greater Portland metro area including Portland, Beaverton, Hillsboro, Tigard, Lake Oswego, Gresham, Milwaukie, Oregon City, Tualatin, and West Linn. We do not currently service areas more than 30 miles from downtown Portland. If you are unsure whether you are in our service area, call us and we will confirm by ZIP code.' },
  { title: 'Business Hours', text: 'Our normal office and scheduling hours are Monday through Saturday, 7:00 AM to 7:00 PM Pacific Time. We are closed on Sundays for non-emergency work. Emergency service is available 24 hours a day, 7 days a week, including Sundays and holidays.' },
  { title: 'How to Book an Appointment', text: 'You can book an appointment three ways: (1) call us at (555) 010-4729, (2) use the booking form on our website, or (3) chat with us right here. For standard appointments we typically have availability within 1 to 2 business days. We offer 2-hour arrival windows and our dispatcher will text you when the technician is on the way.' },
  { title: 'Pricing and Estimates', text: 'We provide upfront, flat-rate pricing — you approve the price before any work begins, so there are no surprises. Estimates for new installations (such as a furnace or AC replacement) are free and include a written quote. For diagnostic visits on a repair, a service fee applies. We do not charge for travel time within our service area.' },
  { title: 'Diagnostic / Service Fee', text: 'A $89 diagnostic fee applies to repair service calls. This covers the technician travelling to your home and diagnosing the problem. If you approve the recommended repair, the $89 fee is fully applied toward the cost of that repair. The diagnostic fee is waived entirely for Northwind Care Club members.' },
  { title: 'Emergency and After-Hours Service', text: 'We offer 24/7 emergency service for urgent issues such as no heat in winter, no cooling during a heat advisory, burst or leaking pipes, sewage backups, sparking outlets, or a complete loss of power. After-hours emergency calls (outside Monday-Saturday 7 AM-7 PM) carry an additional after-hours dispatch fee of $75. Care Club members receive priority emergency scheduling and a waived dispatch fee.' },
  { title: 'HVAC Services', text: 'Our HVAC services include furnace repair and installation, air conditioner repair and installation, heat pump service, ductless mini-split installation, thermostat installation (including smart thermostats), duct cleaning and sealing, and seasonal tune-ups. We service all major brands including Carrier, Trane, Lennox, Rheem, and Goodman.' },
  { title: 'Plumbing Services', text: 'Our plumbing services include leak detection and repair, water heater repair and installation (tank and tankless), drain cleaning and hydro-jetting, toilet and faucet repair, garbage disposal installation, sewer line inspection and repair, repiping, and sump pump service. We do not service septic tank pumping.' },
  { title: 'Electrical Services', text: 'Our electrical services include panel upgrades and replacement, outlet and switch installation, EV charger installation, ceiling fan and lighting installation, whole-home surge protection, generator installation, wiring and rewiring, and electrical safety inspections. All electrical work is performed by licensed electricians and pulled to code with permits where required.' },
  { title: 'Northwind Care Club Membership', text: 'The Northwind Care Club is our maintenance membership plan at $19 per month or $199 per year. Members get: two seasonal HVAC tune-ups per year, an annual plumbing and electrical safety inspection, a waived $89 diagnostic fee, 15% off all repairs, priority scheduling, no after-hours dispatch fee, and a 2-year guarantee on repairs (instead of 1 year). Membership can be cancelled anytime.' },
  { title: 'Warranty and Guarantee', text: 'All repairs are backed by a 1-year workmanship guarantee (2 years for Care Club members). New equipment installations carry the manufacturer warranty (typically 5 to 10 years on parts) plus our 1-year labor warranty. If you are not satisfied with a repair, we will come back and make it right at no additional labor cost within the guarantee period. This is our Northwind Done-Right Promise.' },
  { title: 'Payment Methods and Financing', text: 'We accept all major credit cards (Visa, Mastercard, American Express, Discover), debit cards, cash, and check. For larger projects such as a system replacement, we offer financing with approved credit, including 0% APR plans for qualified customers over 12 months. Payment is due upon completion of the work unless financing has been arranged in advance.' },
  { title: 'Cancellation and Reschedule Policy', text: 'You can cancel or reschedule a standard appointment at no charge as long as you give us at least 4 hours notice. For cancellations with less than 4 hours notice, a $49 trip-reservation fee may apply. To cancel or reschedule, call (555) 010-4729 or reply to your appointment confirmation text.' },
  { title: 'Contact Information', text: 'You can reach Northwind Home Services by phone at (555) 010-4729, by email at hello@northwindhome.example, or through the contact form on our website. Our office is located at 1420 NW Marshall St, Portland, OR 97209. For the fastest response on an urgent issue, please call rather than email.' },
];

// ---- Conversation memory: load recent history + rolling summary for this session ----
let history = [];
let summary = '';
try {
  const sd = $getWorkflowStaticData('global');
  sd.sessions = sd.sessions || {};
  const now = Date.now();
  const ttlMs = Number(cfg.memoryTtlMin || 180) * 60000;
  for (const k of Object.keys(sd.sessions)) {
    if (now - (sd.sessions[k].updated || 0) > ttlMs) delete sd.sessions[k];
  }
  const sess = sd.sessions[sessionId];
  history = (sess && Array.isArray(sess.turns)) ? sess.turns : [];
  summary = (sess && sess.summary) ? sess.summary : '';
} catch (e) {
  history = [];
  summary = '';
}

// Retrieval query = recent user turns + current message, so follow-ups like
// "how much is that?" still retrieve the right KB chunks.
const recentUser = history.filter((t) => t.role === 'user').slice(-2).map((t) => t.text);
const retrievalQuery = [...recentUser, message].join(' \n ').trim() || 'hello';

const model = 'models/' + cfg.embedModel;
const texts = KB.map((c) => c.title + '. ' + c.text);
texts.push(retrievalQuery);

const requests = texts.map((t) => ({ model, content: { parts: [{ text: String(t).slice(0, 8000) }] } }));

return [{ json: {
  message,
  sessionId,
  kb: KB.map((c) => ({ title: c.title, text: c.text })),
  history,
  summary,
  embedBody: { requests },
} }];

// ============================================================================
// Retrieve — Code node (no credentials). Ranks KB chunks by cosine similarity,
// injects the rolling memory note + recent turns, and builds a grounded,
// human-feeling Gemini chat request.
// ============================================================================

const cfg = $('Config').first().json;
const prep = $('Prepare').first().json;
const emb = $json; // batchEmbedContents response

const message = prep.message;
const kb = prep.kb || [];
const vecs = (emb && Array.isArray(emb.embeddings)) ? emb.embeddings : [];

const cosine = (a, b) => {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) + 1e-9);
};

let context = '';
let score = 0;
let sources = [];

if (vecs.length >= kb.length + 1) {
  const qv = vecs[kb.length].values;
  const topK = Number(cfg.topK || 5);
  const ranked = kb
    .map((c, i) => ({ title: c.title, text: c.text, s: cosine(qv, vecs[i].values) }))
    .sort((a, b) => b.s - a.s);
  const top = ranked.slice(0, topK);
  score = top.length ? top[0].s : 0;
  sources = top.map((t) => t.title);
  context = top.map((c) => '[' + c.title + ']\n' + c.text).join('\n\n');
}

// ---- Persona: warm, intelligent, human — not a robotic FAQ ----
const persona = 'You are the friendly virtual assistant for ' + cfg.companyName + ', a trusted, licensed home-services company '
  + '(HVAC, plumbing, and electrical) serving the Greater Portland, Oregon area. '
  + 'You genuinely care about homeowners — keeping their home comfortable and safe, handling urgent problems quickly, and giving honest, upfront answers. '
  + 'You speak like a warm, reassuring, professional customer-service rep, not like a machine. '
  + 'You can help with: services offered (HVAC, plumbing, electrical), service area, hours, booking an appointment, pricing and estimates, '
  + 'the diagnostic fee, emergency / after-hours service, the Care Club membership, warranties, payment and financing, the cancellation policy, and contact info.';

const memoryNote = prep.summary
  ? '\n\nMEMORY NOTE — durable facts from earlier in this same conversation (treat as true and use naturally):\n' + prep.summary
  : '';

const style = '\n\nHOW TO TALK (be human and intelligent):\n'
  + '- Be warm, natural, and personable. Vary your wording; never sound canned or repeat the same sentences.\n'
  + '- Once you know the customer\'s name, use it occasionally and naturally.\n'
  + '- Show genuine empathy, especially for stressful situations (no heat in winter, a flooding pipe, a power outage).\n'
  + '- REASON about what they really need: connect services to their situation. '
  + 'E.g. "my furnace died and it\'s freezing" → recognize it is urgent and point to 24/7 emergency service; '
  + 'someone worried about cost → mention upfront flat-rate pricing or the Care Club.\n'
  + '- If a question is ambiguous, ask one short, friendly clarifying question instead of guessing.\n'
  + '- For multi-part questions, address each part. Keep replies focused (usually 2-5 sentences) — helpful, not a wall of text.\n'
  + '- Never say "as an AI" or dismiss yourself as "just a bot". Be confident and personable.';

const rules = '\n\nIMPORTANT RULES:\n'
  + '1. FACTS: For concrete facts (prices, fees, hours, service area, policies, what is/ isn\'t serviced) use ONLY the CONTEXT below. Never invent or guess them. You MAY reason, empathize, and make natural suggestions around those facts.\n'
  + '2. MEMORY: Use the MEMORY NOTE and the conversation history. Remember the customer\'s name, where they live, and what they asked. If they ask whether you remember them or what they told you, recall it confidently. NEVER claim you cannot remember things from this conversation.\n'
  + '3. Greetings, thanks, self-introductions, and questions about you — respond warmly. Do NOT hand off.\n'
  + '4. Truly unrelated topics (other companies, general trivia, jokes, the weather, coding) — gently steer back to how ' + cfg.companyName + ' can help. Do NOT hand off. (A customer sharing their name, location, or home issue is NOT off-topic — welcome it.)\n'
  + '5. HUMAN HAND-OFF — for a matter that needs a real person (booking or changing a specific appointment time, an existing job or complaint, a billing / refund / invoice dispute, a warranty claim, a custom quote for their exact system, or anything you genuinely cannot resolve from the facts): do NOT just deflect. FIRST reply warmly and helpfully — acknowledge their specific situation, share anything relevant you do know (e.g. how booking works, the warranty policy, the after-hours fee), and let them know you are connecting them with the ' + cfg.companyName + ' team and that they can call ' + cfg.supportContact + '. THEN add a final line containing ONLY the marker [[HANDOFF]] — this marker line is removed before the customer sees it, so never explain it.\n'
  + '6. Do not mention the word "context" or say you are reading from documents.\n'
  + '7. When it fits naturally, invite the customer to book an appointment or call.\n'
  + '8. Reply in the language the customer wrote in.';

const sys = persona + memoryNote + style + rules;

// ---- Recent verbatim turns (the rolling summary covers older history) ----
let history = Array.isArray(prep.history) ? prep.history.slice() : [];
while (history.length && history[0].role !== 'user') history.shift(); // Gemini needs a user-first turn
const historyContents = history.map((t) => ({
  role: t.role === 'model' ? 'model' : 'user',
  parts: [{ text: String(t.text || '') }],
}));

const chatBody = {
  systemInstruction: { parts: [{ text: sys }] },
  contents: [
    ...historyContents,
    { role: 'user', parts: [{ text: 'CONTEXT (facts you may use):\n' + (context || '(no relevant information found)') + '\n\nCUSTOMER MESSAGE: ' + message }] },
  ],
  generationConfig: {
    temperature: Number(cfg.chatTemperature || 0.55),
    topP: 0.95,
    maxOutputTokens: 700,
  },
};

return [{ json: { message, sessionId: prep.sessionId, score: Number(score.toFixed(3)), sources, chatBody } }];

// ============================================================================
// Decide — Code node (no credentials). Parses Gemini's answer, handles the warm
// hand-off marker, decides escalation, and saves the exchange to memory.
// ============================================================================

const cfg = $('Config').first().json;
const ret = $('Retrieve').first().json;
const chat = $json; // generateContent response

let answer = '';
try {
  answer = chat.candidates[0].content.parts.map((p) => p.text || '').join('').trim();
} catch (e) {
  answer = '';
}

// The model writes a warm, contextual reply and appends a [[HANDOFF]] marker line
// when a human should follow up — we strip the marker but KEEP the helpful reply,
// so the customer is answered first, never cold-deflected. Bare "ESCALATE" (legacy)
// or an empty answer falls back to a friendly default.
const HANDOFF_RE = /\[\[\s*hand\s*-?\s*off\s*\]\]/gi;
const norm = answer.toUpperCase().replace(/[^A-Z]/g, '');
let escalate = false;

if (HANDOFF_RE.test(answer)) {
  escalate = true;
  answer = answer.replace(HANDOFF_RE, '').replace(/\n{3,}/g, '\n\n').trim();
}

if (!answer || norm === 'ESCALATE') {
  escalate = true;
  answer = 'Thanks for reaching out! I want to make sure you get an accurate answer, so I\'ve passed this to the '
    + cfg.companyName + ' team. You can also reach us anytime at ' + cfg.supportContact + ' and we\'ll be glad to help.';
}

// Safety net: if we're handing off but the reply didn't say how to reach us, add it.
if (escalate && answer && cfg.supportContact && !answer.includes(cfg.supportContact)) {
  answer += '\n\nYou can also reach our team directly at ' + cfg.supportContact + '.';
}

// ---- Conversation memory: persist this exchange for the session ----
try {
  const sd = $getWorkflowStaticData('global');
  sd.sessions = sd.sessions || {};
  const sess = sd.sessions[ret.sessionId] || { turns: [], summary: '' };
  sess.turns = sess.turns || [];
  sess.turns.push({ role: 'user', text: ret.message });
  sess.turns.push({ role: 'model', text: answer });
  const maxTurns = Number(cfg.memoryMaxTurns || 24);
  if (sess.turns.length > maxTurns) sess.turns = sess.turns.slice(-maxTurns);
  sess.updated = Date.now();
  sd.sessions[ret.sessionId] = sess;
  const keys = Object.keys(sd.sessions);
  if (keys.length > 500) {
    keys.sort((a, b) => (sd.sessions[a].updated || 0) - (sd.sessions[b].updated || 0));
    for (let i = 0; i < keys.length - 500; i++) delete sd.sessions[keys[i]];
  }
} catch (e) {
  /* memory is best-effort */
}

return [{ json: {
  reply: answer,
  escalate,
  score: ret.score,
  sources: ret.sources,
  message: ret.message,
  sessionId: ret.sessionId,
} }];

// ============================================================================
// Memory Maintenance — Code node (no credentials). Runs AFTER the reply is sent.
// If the verbatim turn buffer has grown past the summarize threshold, it builds
// a prompt to fold the older turns into a rolling MEMORY NOTE (durable facts).
// Outputs { skip:true } when no summarization is needed.
// ============================================================================

const cfg = $('Config').first().json;
const ret = $('Decide').first().json;
const sid = ret.sessionId;

let out = { skip: true, sessionId: sid };
try {
  const sd = $getWorkflowStaticData('global');
  sd.sessions = sd.sessions || {};
  const sess = sd.sessions[sid] || { turns: [], summary: '' };
  const turns = sess.turns || [];

  const summarizeAt = Number(cfg.memorySummarizeAt || 16);
  const keep = Number(cfg.memoryKeep || 12);

  if (turns.length > summarizeAt) {
    const overflow = turns.slice(0, turns.length - keep);
    const convoText = overflow
      .map((t) => (t.role === 'user' ? 'Customer: ' : 'Assistant: ') + String(t.text || ''))
      .join('\n');

    const prompt = 'You maintain a concise running MEMORY NOTE for an ongoing customer-support chat for ' + (cfg.companyName || 'the company') + '. '
      + 'Rewrite the memory note so it captures the durable facts worth remembering about THIS customer and conversation: '
      + 'their name, where they live, their home issue or the service they need, their concerns or sentiment, and anything you promised or recommended. '
      + 'Be factual and third-person, no fluff, under 150 words. Merge the existing note with the new lines; drop nothing important.\n\n'
      + 'EXISTING MEMORY NOTE:\n' + (sess.summary || '(none yet)') + '\n\n'
      + 'NEW CONVERSATION LINES TO FOLD IN:\n' + convoText + '\n\nUPDATED MEMORY NOTE:';

    out = {
      skip: false,
      sessionId: sid,
      summaryBody: {
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0.2, maxOutputTokens: 320 },
      },
    };
  }
} catch (e) {
  out = { skip: true, sessionId: sid, error: String((e && e.message) || e) };
}

return [{ json: out }];

// ============================================================================
// Apply Summary — Code node (no credentials). Runs after the summarizer LLM call.
// Writes the updated MEMORY NOTE and trims the verbatim turn buffer to the last
// `memoryKeep` turns. Best-effort; never throws.
// ============================================================================

const cfg = $('Config').first().json;
const mm = $('Memory Maintenance').first().json;
const sid = mm.sessionId;
const chat = $json; // Summarize response

let newSummary = '';
try {
  newSummary = chat.candidates[0].content.parts.map((p) => p.text || '').join('').trim();
} catch (e) {
  newSummary = '';
}

try {
  if (newSummary) {
    const sd = $getWorkflowStaticData('global');
    sd.sessions = sd.sessions || {};
    const sess = sd.sessions[sid];
    if (sess) {
      const keep = Number(cfg.memoryKeep || 12);
      sess.summary = newSummary.slice(0, 1500);
      sess.turns = (sess.turns || []).slice(-keep);
      sess.updated = Date.now();
      sd.sessions[sid] = sess;
    }
  }
} catch (e) {
  /* best-effort */
}

return [{ json: { ok: true, sessionId: sid, summaryUpdated: Boolean(newSummary) } }];
